def validate_all():
    missing, errors, warnings = ([], [], [])
    if facility_name == '選択してください':
        missing.append('施設名')
    if not registration_id:
        missing.append('JUOG登録番号')
    elif not valid_registration_id(registration_id):
        errors.append('JUOG登録番号の形式が不正です（例：JUOG-001）')
    if not text(reporter_email):
        missing.append('担当者メールアドレス')
    elif not valid_email(reporter_email):
        errors.append('担当者メールアドレスが不正です')
    if submission_kind == '訂正報告' and (not text(correction_reason)):
        missing.append('訂正理由')
    if surgery_performed is None:
        missing.append('手術実施有無')
    elif planned_or_reference_date is None:
        missing.append('手術実施日' if surgery_performed == '実施した' else '手術予定日')
    if surgery_performed is not None and last_evp_date is None:
        missing.append('EVP最終投与日')
    if surgery_performed == '実施した':
        for v, label in [(op_admission_date, '入院日'), (op_date, '手術実施日')]:
            if v is None:
                missing.append(label)
        if initial_hospital_outcome is None:
            missing.append('初回手術入院の転帰')
        if initial_hospital_outcome == '退院済み' and op_discharge_date is None:
            missing.append('初回退院日')
        if op_type == '選択してください':
            missing.append('術式')
        if op_type == 'その他（プロトコル逸脱）' and (not text(st.session_state.get('peri_op_other', ''))):
            missing.append('実施術式詳細')
        if not approaches:
            missing.append('アプローチ')
        if len(approaches) >= 2 and approach_pattern == '':
            missing.append('複数アプローチの区分')
        if approach_pattern == '予定外のアプローチ変更（conversion）' and (not text(conversion_reason)):
            missing.append('conversionの理由')
        if op_completed is None:
            missing.append('手術完遂')
        if op_completed == 'いいえ' and (not text(op_incomplete_detail)):
            missing.append('完遂不能理由')
        if op_time is None or op_time <= 0:
            missing.append('手術時間')
        if bleeding is None:
            missing.append('出血量')
        if eau_grade == '選択してください':
            missing.append('EAUiaiC')
        if eau_grade not in ['選択してください', 'Grade 0'] and (not text(eau_detail)):
            missing.append('術中合併症詳細')
        if ln_dissection is None:
            missing.append('リンパ節郭清')
        if ln_dissection == '実施した' and (not ln_range):
            missing.append('郭清範囲')
        if unrecovered_g2_relevant is None:
            missing.append('手術時未回復Grade 2以上AE')
        if unrecovered_g2_relevant == 'あり' and (not text(st.session_state.get('peri_g2_detail', ''))):
            missing.append('未回復AE詳細')
        if op_date and last_evp_date:
            wd = (op_date - last_evp_date).days
            if last_evp_date > op_date:
                errors.append('EVP最終投与日が手術実施日より後です')
            if (wd > 56 or wd < 28) and (not text(protocol_deviation_reason)):
                missing.append('手術時期の理由/逸脱理由')
        if op_admission_date and op_date and (op_admission_date > op_date):
            errors.append('入院日が手術日より後です')
        if op_discharge_date and op_date and (op_discharge_date < op_date):
            errors.append('初回退院日が手術日より前です')
        if op_discharge_date and op_admission_date and (op_discharge_date < op_admission_date):
            errors.append('初回退院日が入院日より前です')
        if initial_hospital_outcome == '退院済み':
            if op_discharge_date and op_date and (op_discharge_date <= op_date + timedelta(days=30)) and (readmission_30d is None):
                missing.append('術後30日以内の再入院')
            elif readmission_30d == 'あり':
                if readmission_date is None:
                    missing.append('再入院日')
                if not text(readmission_reason):
                    missing.append('再入院理由')
                if readmission_day30_status is None:
                    missing.append('再入院後の転帰')
                if readmission_day30_status == '再退院済み' and readmission_discharge_date is None:
                    missing.append('再退院日')
                if readmission_date and op_discharge_date and (readmission_date < op_discharge_date):
                    errors.append('再入院日が初回退院日より前です')
                if readmission_date and op_date and (readmission_date > op_date + timedelta(days=30)):
                    errors.append('再入院日は術後30日以内の日付を入力してください')
                if readmission_discharge_date and readmission_date and (readmission_discharge_date < readmission_date):
                    errors.append('再退院日が再入院日より前です')
        if op_type == 'その他（プロトコル逸脱）':
            warnings.append('術式が計画書規定（RNU/尿管部分切除術）外です')
        if unrecovered_g2_relevant == 'あり':
            warnings.append('手術時点で手術手技に影響しうるGrade 2以上未回復AEあり：プロトコル適合性を確認してください')
        for key, label in [('histology', '病理組織型'), ('ypt', 'ypT'), ('lvi', 'LVI'), ('r0', 'R0'), ('trg', 'TRG')]:
            if path.get(key) in [None, '', '選択してください']:
                missing.append(label)
        if path.get('histology') == 'その他' and (not text(path.get('histology_other'))):
            missing.append('病理組織型その他詳細')
        if path.get('subtype_presence') is None:
            missing.append('亜型/分化')
        if path.get('subtype_presence') == 'あり' and (not path.get('subtypes')):
            missing.append('亜型/分化の種類')
        if path.get('size_mm') is None:
            missing.append('病理最大径')
        if not path.get('locations'):
            missing.append('病理部位')
        if path.get('ypn') in [None, '', '選択してください']:
            missing.append('ypN')
        if ln_dissection == '実施した' and path.get('ln_count_examined') is None:
            missing.append('摘出リンパ節数（病理検索数）')
        if path.get('ypn') in ['ypN1', 'ypN2'] and (not path.get('ypn_sites')):
            missing.append('ypN陽性部位')
        if (path.get('ypn') == 'ypNX（評価不能）' or '評価不能' in [path.get('histology'), path.get('ypt'), path.get('lvi'), path.get('r0'), path.get('trg')]) and (not text(path.get('eval_failed_reason'))):
            missing.append('病理評価不能理由')
    elif surgery_performed == '実施しなかった':
        if no_op_reason == '選択してください':
            missing.append('手術未施行理由')
        if no_op_reason == 'その他' and (not text(st.session_state.get('peri_noop_other', ''))):
            missing.append('手術未施行理由その他詳細')
    discharge_labs_parsed, discharge_labs_errors = validate_optional_lab_panel(discharge_labs_raw)
    errors.extend([f'退院前最終採血：{x}' for x in discharge_labs_errors])
    if surgery_performed == '実施した':
        for v, label in [(day0_sbp, '術後管理場所到着時 収縮期血圧'), (day0_dbp, '術後管理場所到着時 拡張期血圧'), (day0_pulse, '術後管理場所到着時 脈拍'), (day0_temp, '術後管理場所到着時 体温')]:
            if v is None:
                missing.append(label)
        errors.extend(validate_vitals(day0_sbp, day0_dbp, day0_pulse, day0_temp, '術後管理場所到着時バイタル'))
        if initial_hospital_outcome == '退院済み':
            for v, label in [(discharge_sbp, '退院時 収縮期血圧'), (discharge_dbp, '退院時 拡張期血圧'), (discharge_pulse, '退院時 脈拍'), (discharge_temp, '退院時 体温')]:
                if v is None:
                    missing.append(label)
            errors.extend(validate_vitals(discharge_sbp, discharge_dbp, discharge_pulse, discharge_temp, '退院時バイタル'))
            if discharge_lab_available is None:
                missing.append('退院前採血の有無')
            elif discharge_lab_available == 'あり':
                if discharge_lab_date is None:
                    missing.append('退院前採血日')
                if not any((text(v) for v in discharge_labs_raw.values())):
                    missing.append('退院前採血結果')
                if discharge_lab_date and op_date and (discharge_lab_date < op_date):
                    errors.append('退院前採血日が手術日より前です')
                if discharge_lab_date and op_discharge_date and (discharge_lab_date > op_discharge_date):
                    errors.append('退院前採血日が初回退院日より後です')
    if visit_date_30 is None:
        missing.append('30日評価日')
    if reference_date and visit_date_30:
        wi = window_info(reference_date, 30, 14)
        if visit_date_30 < reference_date:
            errors.append('30日評価日が手術/予定日より前です')
        if visit_date_30 > today_jst():
            errors.append('30日評価日が未来日です')
        if not wi['min'] <= visit_date_30 <= wi['max']:
            if not text(window_deviation_reason):
                missing.append('30日評価時期の逸脱理由')
            warnings.append('30日評価日が30日±14日の範囲外です')
    day30_parsed, day30_errors = validate_optional_lab_panel(day30_labs_raw)
    errors.extend([f'30日血液検査：{x}' for x in day30_errors])
    if day30_lab_date is None:
        missing.append('30日評価に用いた採血日')
    if not any((text(v) for v in day30_labs_raw.values())):
        missing.append('30日評価採血結果')
    if reference_date and day30_lab_date:
        lab_wi = window_info(reference_date, 30, 14)
        if not lab_wi['min'] <= day30_lab_date <= lab_wi['max']:
            errors.append('30日評価に用いた採血日が30日±14日の許容期間外です')
    if surgery_performed == '実施した':
        if cd_grade == '選択してください':
            missing.append('30日CD Grade')
        if cd_grade not in ['選択してください', 'Grade 0']:
            if cd_date is None:
                missing.append('合併症発現日')
            if not text(cd_detail):
                missing.append('合併症詳細')
            if cd_relation == '選択してください':
                missing.append('手術手技との因果関係')
            if renal_exception and (not text(renal_exception_detail)):
                missing.append('腎機能低下/透析除外規定の根拠')
            if op_date and cd_date:
                if cd_date < op_date:
                    errors.append('合併症発現日が手術日より前です')
                if cd_date > op_date + timedelta(days=30):
                    errors.append('30日CRFの手術関連合併症は術後30日以内の日付を入力してください')
    if has_ctcae and (not text(ctcae_detail)):
        missing.append('CTCAE有害事象詳細')
    if adj_plan == '選択してください':
        missing.append('術後治療')
    if adj_plan in ['治験（TROP2標的ADC、その他）', 'その他'] and (not text(adj_detail)):
        missing.append('術後治療詳細')
    if adj_plan not in ['選択してください', '無治療（経過観察）'] and adj_start is None:
        missing.append('術後治療開始日')
    if adj_start and adj_end and (adj_end < adj_start):
        errors.append('術後治療終了日が開始日より前です')
    if initial_hospital_outcome == '初回入院中に死亡' and status_alive not in [None, '死亡']:
        errors.append('初回入院中死亡が選択されています。生存状況は『死亡』としてください')
    if readmission_day30_status == '再入院中に死亡' and status_alive not in [None, '死亡']:
        errors.append('再入院中死亡が選択されています。生存状況は『死亡』としてください')
    if status_alive is None:
        missing.append('生存状況')
    elif status_alive == '生存':
        if final_visit_date is None:
            missing.append('最終生存確認日')
        else:
            if final_visit_date > today_jst():
                errors.append('最終生存確認日が未来日です')
            if visit_date_30 and final_visit_date < visit_date_30:
                warnings.append('最終生存確認日が30日評価日より前です。30日評価時に生存確認している場合は評価日を入力してください')
        if cd_grade == 'Grade V':
            errors.append('CD Grade Vですが生存状況が『生存』です')
    else:
        if death_date is None:
            missing.append('死亡日')
        elif death_date > today_jst():
            errors.append('死亡日が未来日です')
        if death_cause == '選択してください':
            missing.append('死因')
        if surgery_performed == '実施した' and death_date and op_date and (death_date < op_date):
            errors.append('死亡日が手術実施日より前です')
    return (unique_messages(missing), unique_messages(errors), unique_messages(warnings), discharge_labs_parsed, day30_parsed)

day90.source:
def validate_all():
    missing, errors, warnings = ([], [], [])
    if not facility_name or facility_name == '選択してください':
        missing.append('施設名')
    if not registration_id:
        missing.append('JUOG登録番号')
    elif not valid_registration_id(registration_id):
        errors.append('JUOG登録番号の形式が不正です（例：JUOG-001）')
    if not text(reporter_email):
        missing.append('担当者メールアドレス')
    elif not valid_email(reporter_email):
        errors.append('担当者メールアドレスが不正です')
    if submission_kind == '訂正報告' and (not text(correction_reason)):
        missing.append('訂正理由')
    if surgery_performed not in ['実施した', '実施しなかった']:
        missing.append('手術実施有無')
    if reference_date is None:
        missing.append('手術日' if surgery_performed == '実施した' else '手術予定日')
    if visit_date is None:
        missing.append('90日評価日')
    if reference_date and visit_date:
        wi = window_info(reference_date, 90, 14)
        if visit_date < reference_date:
            errors.append('90日評価日が手術/予定日より前です')
        if visit_date > today_jst():
            errors.append('90日評価日が未来日です')
        if not wi['min'] <= visit_date <= wi['max']:
            warnings.append('90日評価日が90日±14日の範囲外です')
            if not text(visit_deviation_reason):
                missing.append('90日評価時期の逸脱理由')
    parsed_labs, lab_errors = validate_optional_lab_panel(labs_raw)
    errors.extend([f'90日血液検査：{x}' for x in lab_errors])
    if lab_available is None:
        missing.append('90日評価期間内の採血有無')
    elif lab_available == 'あり':
        if lab_date is None:
            missing.append('90日評価に用いた採血日')
        if not any((text(v) for v in labs_raw.values())):
            missing.append('90日評価採血結果')
        if lab_date and reference_date:
            wi_lab = window_info(reference_date, 90, 14)
            if not wi_lab['min'] <= lab_date <= wi_lab['max']:
                errors.append('90日評価に用いた採血日が90日±14日の許容期間外です')
        if lab_date and lab_date > today_jst():
            errors.append('90日評価に用いた採血日が未来日です')
        if lab_date and visit_date and (lab_date > visit_date):
            warnings.append('90日採血日が90日評価日より後です')
    missing.extend([f'90日{x}' for x in validate_cytology(cytology, required=True)])
    if cytology == '未実施' and (not text(required_test_omission_reason)):
        missing.append('尿細胞診未実施理由')
    if imaging_status is None:
        missing.append('画像検査実施有無')
    elif imaging_status == '実施':
        if imaging_date is None:
            missing.append('画像検査日')
        if recist_status == '選択してください':
            missing.append('RECIST進行判定')
        if recist_status == 'PDあり':
            if progression_date is None:
                missing.append('RECIST PD確認日')
            if not progression_sites:
                missing.append('進行/新病変部位')
            if not text(progression_detail):
                missing.append('進行所見詳細')
    elif not text(imaging_not_done_reason):
        missing.append('画像検査未実施理由')
    if cystoscopy_status is None:
        missing.append('膀胱鏡実施有無')
    elif cystoscopy_status == '実施':
        if cystoscopy_date is None:
            missing.append('膀胱鏡日')
        if cystoscopy_result == '選択してください':
            missing.append('膀胱鏡所見')
        if cystoscopy_result in ['腫瘍あり', '評価不能'] and (not text(cystoscopy_detail)):
            missing.append('膀胱鏡所見詳細')
    elif not text(cystoscopy_not_done_reason):
        missing.append('膀胱鏡未実施理由')
    for d, label in [(imaging_date, '画像検査日'), (cystoscopy_date, '膀胱鏡日'), (progression_date, 'PD確認日')]:
        if d and visit_date and (d > visit_date):
            errors.append(f'{label}が90日評価日より後です')
        if d and d > today_jst():
            errors.append(f'{label}が未来日です')
        if d and reference_date and (label in ['画像検査日', '膀胱鏡日']):
            wi_test = window_info(reference_date, 90, 14)
            if not wi_test['min'] <= d <= wi_test['max']:
                warnings.append(f'{label}が90日±14日の目安範囲外です')
    if surgery_performed == '実施した':
        if new_complication is None:
            missing.append('31〜90日新規手術関連合併症')
        if new_complication == 'あり':
            if cd_grade in ['選択してください', 'Grade 0', 'N/A']:
                missing.append('Clavien-Dindo Grade')
            if cd_date is None:
                missing.append('合併症発現日')
            if not text(cd_detail):
                missing.append('合併症詳細')
            if cd_relation == '選択してください':
                missing.append('手術手技との因果関係')
            if renal_exception and (not text(renal_exception_detail)):
                missing.append('腎機能低下/透析除外規定の根拠')
            if cd_date and reference_date:
                d = (cd_date - reference_date).days
                if d <= 30:
                    errors.append('31〜90日合併症欄には術後31日以降の事象を入力してください（30日以内は30日CRFの訂正報告）')
                if d > 90:
                    errors.append('90日手術関連合併症の評価対象は術後90日以内です')
    if has_ctcae and (not text(ctcae_detail)):
        missing.append('CTCAE有害事象詳細')
    if intra_status is None:
        missing.append('尿路内再発の有無')
    if intra_status == 'あり':
        if intra_date is None:
            missing.append('尿路内再発診断日')
        if not intra_sites:
            missing.append('尿路内再発部位')
        if 'その他' in intra_sites and (not text(intra_site_other)):
            missing.append('尿路内再発部位その他詳細')
        if not intra_tx:
            missing.append('尿路内再発の対応/治療')
        if '経過観察' in intra_tx and len(intra_tx) > 1:
            errors.append('尿路内再発治療で『経過観察』と他治療を同時選択できません')
        if 'その他' in intra_tx and (not text(intra_tx_other)):
            missing.append('尿路内治療その他詳細')
        if intra_tx and '経過観察' not in intra_tx and (intra_tx_status is None):
            missing.append('尿路内再発治療の状況')
        if intra_tx_status == '実施済み・継続中':
            if any((x in intra_tx for x in ['TURBT', '上部尿路内視鏡的治療', '手術（腎尿管全摘等）'])):
                if intra_procedure_date is None:
                    missing.append('尿路内再発処置/手術日')
                if not text(intra_path):
                    missing.append('尿路内再発病理')
            if any((x in intra_tx for x in ['BCG注入療法', '抗がん剤注入療法'])):
                if intra_instill_start is None:
                    missing.append('尿路内注入療法開始日')
                if not intra_instill_ongoing and intra_instill_end is None:
                    missing.append('尿路内注入療法終了日')
                if intra_instill_start and intra_instill_end and (intra_instill_end < intra_instill_start):
                    errors.append('尿路内注入療法終了日が開始日より前です')
        for dt, label in [(intra_procedure_date, '尿路内再発処置日'), (intra_instill_start, '尿路内注入療法開始日'), (intra_other_date, '尿路内その他治療日')]:
            if intra_date and dt and (dt < intra_date):
                errors.append(f'{label}が再発診断日より前です')
    if adj_plan == '選択してください':
        missing.append('術後治療')
    if adj_plan in ['治験（TROP2標的ADC、その他）', 'その他'] and (not text(adj_detail)):
        missing.append('術後治療詳細')
    if adj_plan not in ['選択してください', '無治療（経過観察）'] and adj_start is None:
        missing.append('術後治療開始日')
    if adj_start and adj_end and (adj_end < adj_start):
        errors.append('術後治療終了日が開始日より前です')
    if vital_status is None:
        missing.append('生存状況')
    elif vital_status == '生存':
        if last_alive_date is None:
            missing.append('最終生存確認日')
        if cd_grade == 'Grade V':
            errors.append('CD Grade Vですが生存状況が生存です')
    else:
        if death_date is None:
            missing.append('死亡日')
        if death_cause == '選択してください':
            missing.append('死因')
    for d, label in [(last_alive_date, '最終生存確認日'), (death_date, '死亡日')]:
        if d and d > today_jst():
            errors.append(f'{label}が未来日です')
    return (unique_messages(missing), unique_messages(errors), unique_messages(warnings), parsed_labs)

